        a = float(a.replace(',', '.')) if ',' in a else float(a)
    if isinstance(b, str):
        b = float(b.replace(',', '.')) if ',' in b else float(b)

    # Compare the values to find the larger one
    if a > b:
        return a
    elif b > a:
        return b
    else:
        return None
